const fs = require('fs');

const readme = fs.readFileSync('README.md', 'utf8');
const headings = readme
  .split(/\r?\n/)
  .filter((line) => line.startsWith('#'));

fs.writeFileSync('INDEX.md', headings.length ? headings.join('\n') + '\n' : '');

